source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    fill = set()
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    border = {grid[top][c] for c in range(left, right + 1)}
                    border.update(grid[bottom][c] for c in range(left, right + 1))
                    border.update(grid[r][left] for r in range(top, bottom + 1))
                    border.update(grid[r][right] for r in range(top, bottom + 1))
                    if len(border) != 1 or background in border:
                        continue
                    if all(grid[r][c] == background
                           for r in range(top + 1, bottom)
                           for c in range(left + 1, right)):
                        fill.update((r, c)
                                    for r in range(top + 1, bottom)
                                    for c in range(left + 1, right))
    return [[4 if (r, c) in fill else value
             for c, value in enumerate(row)] for r, row in enumerate(grid)]
